  "scenarios": [
    {
      "id": "MOCK-01",
      "name": "Успешная заметка",
      "testIds": [
        "TST-01",
        "TST-02",
        "TST-08"
      ],
      "taskIds": [
        "T-01",
        "T-02",
        "T-03"
      ],
      "operation": "POST /notes с валидным синтетическим CreateNote; Note ответа соответствует схеме.",
      "fixture": "mocks/fixtures/data.json#/fixtures/success",
