          "taskId": "T-01",
          "path": "mocks/fixtures/note_repository.json",
          "pointer": "#/fixtures/success"
        },
        {
          "taskId": "T-02",
          "path": "mocks/fixtures/api_notes.json",
          "pointer": "#/fixtures/success"
        },
        {
          "taskId": "T-03",
          "path": "mocks/fixtures/notes.json",
          "pointer": "#/fixtures/success"
        }
